// src/mcp/callToolHandler.ts
function createCallToolHandler(searcherFactory = initializeSearchers) {
  const scholarReferenceCache = new ScholarReferenceCache();
  const handler = async (request, extra) => {
    const { name, arguments: args } = request.params;
    logDebug(`Received tools/call request: ${name}`);
    try {
      const parsedArgs = parseToolArgs(name, args);
      const preflight = await preflightPublicToolCall(name, parsedArgs, scholarReferenceCache);
      if (preflight) return preflight;
      const currentSearchers = searcherFactory();
      const operation = currentSearchers.retrievalService.createOperation({
        signal: extra.signal,
        purpose: retrievalPurposeForToolCall(name, parsedArgs)
      });
      try {
        return await handleToolCall(name, parsedArgs, currentSearchers, operation, {
          scholarReferenceCache
        });
      } finally {
        operation.dispose();
      }
    } catch (error62) {
      logDebug(`Error in tool ${name}:`, error62);
      return {
        content: [
          {
            type: "text",
            text: `Error executing tool '${name}': ${sanitizeSensitiveText(error62?.message || "Unknown error occurred")}`
          }
        ],
        isError: true
      };
    }
  };
  handler.dispose = () => scholarReferenceCache.dispose();
  return handler;
}

// src/mcp/registerHandlers.ts
init_Logger();
function registerMcpHandlers(server2, searcherFactory = initializeSearchers) {
  server2.setRequestHandler(InitializeRequestSchema, async (request) => {
    logDebug("Received initialize request:", request.params);
    return {
      protocolVersion: "2024-11-05",
      capabilities: {
        tools: {
          listChanged: true
        }
      },
      serverInfo: {
        name: "twosci",
        version: "0.1.0"
      }
    };
  });
  server2.setRequestHandler(PingRequestSchema, async () => {
    logDebug("Received ping request");
    return {};
  });
  server2.setRequestHandler(ListToolsRequestSchema, async () => {
    logDebug("Received tools/list request");
    return { tools: TOOLS };
  });
  const callToolHandler = createCallToolHandler(searcherFactory);
  server2.setRequestHandler(CallToolRequestSchema, callToolHandler);
  const previousOnClose = server2.onclose;
  server2.onclose = () => {
    callToolHandler.dispose();
    previousOnClose?.();
  };
}

